// TrySet tries to set a value by the multipart request with the binding a form file
func (r *multipartRequest) TrySet(value reflect.Value, field reflect.StructField, key string, opt setOptions) (bool, error) {
	if files := r.MultipartForm.File[key]; len(files) != 0 {
		return setByMultipartFormFile(value, field, files)
	}

	// A file input with an empty filename is parsed as a regular form value
	// instead of a multipart file. Do not try to bind it as a form value, so
	// that optional file fields are simply left untouched (e.g. nil pointers).
	if isMultipartFileField(field.Type) {
		return false, nil
	}

	return setByForm(value, field, r.MultipartForm.Value, key, opt)
}

func isMultipartFileField(t reflect.Type) bool {
	fileHeaderType := reflect.TypeOf(multipart.FileHeader{})
	fileHeaderPtrType := reflect.TypeOf(&multipart.FileHeader{})

	if t == fileHeaderType || t == fileHeaderPtrType {
		return true
	}

	if t.Kind() == reflect.Slice || t.Kind() == reflect.Array {
		elem := t.Elem()
		return elem == fileHeaderType || elem == fileHeaderPtrType
	}

	return false
}

